# Stage labels as the contact pages wrote them in "Pipeline stage changed to ..." notes.
STAGE_LABELS = {
    "Inquiry": "inquiry",
    "Consultation": "consultation",
    "Retained": "retained",
    "Active matter": "active",
    "Closed": "closed",
    "Not retained": "lost",
}
PREFIX = "Pipeline stage changed to "


def backfill(apps, schema_editor):
    """Rebuild stage history from the notes the CRM already wrote on stage changes.

    A contact with no such notes is recorded as entering its current stage when
    it was created.
    """
    Contact = apps.get_model("crm", "Contact")
    Activity = apps.get_model("crm", "Activity")
    StageChange = apps.get_model("reports", "StageChange")
    changes = []
    changed_contacts = set()
    notes = Activity.objects.filter(
        kind="status", contact__isnull=False, subject__startswith=PREFIX
    ).order_by("contact_id", "occurred_at", "pk")
    previous = {}
    for note in notes.iterator():
        stage = STAGE_LABELS.get(note.subject[len(PREFIX) :])
        if stage is None:
            continue
        changed_contacts.add(note.contact_id)
        changes.append(
            StageChange(
                contact_id=note.contact_id,
                from_stage=previous.get(note.contact_id, ""),
                to_stage=stage,
                changed_at=note.occurred_at,
            )
        )
        previous[note.contact_id] = stage
    for contact in Contact.objects.exclude(pk__in=changed_contacts).only("pk", "stage", "created_at"):
        changes.append(
            StageChange(contact_id=contact.pk, to_stage=contact.stage, changed_at=contact.created_at)
        )
    StageChange.objects.bulk_create(changes, batch_size=500)


